import * as THREE from '../vendor/three.module.js';
import {curve,smooth,clamp,branchMesh,seeded} from './geometry.js';
import {leafGeometry,thinLeafMaterial} from './leaf.js';
import {GrowthGraph,addRootNetwork} from './growth.js';
export function createCoffeeStudy({textures}){
 const root=new THREE.Group(),graph=new GrowthGraph(),underground=new THREE.Group(),shoot=new THREE.Group();root.add(underground,shoot);underground.visible=false;const rand=seeded(217);
 const rootMat=new THREE.MeshStandardMaterial({color:0xa79673,roughness:.94}),stemMat=new THREE.MeshStandardMaterial({color:0x657030,roughness:.68});addRootNetwork(graph,underground,rootMat);
 const seedMat=new THREE.MeshStandardMaterial({color:0x746448,roughness:.8});const seed=new THREE.Mesh(new THREE.SphereGeometry(.07,18,12),seedMat);seed.scale.set(1,1.25,.68);seed.position.y=-.03;root.add(seed);
 const stemPoints=Array.from({length:14},(_,i)=>[.045*Math.sin(i*.5),i*.245,.025*Math.cos(i*.7)-.025]);const stem=graph.add({id:'main-stem',path:curve(stemPoints),radius:.037,birth:.08,duration:.58,kind:'shoot',material:stemMat,segments:90,sides:14});shoot.add(stem.mesh);
 const material=thinLeafMaterial(textures,{transmission:.14});material.roughness=.48;material.bumpScale=.007;material.userData.study='coffee thin-wall adaptation';const nodes=[],flowers=[],berries=[];
 for(let n=0;n<10;n++){const at=.16+n*.082,base=stem.path.getPointAt(at),yaw=n*Math.PI/2+.28;const birth=stem.birth+stem.duration*at;
  for(let side=0;side<2;side++){const angle=yaw+side*Math.PI,dir=new THREE.Vector3(Math.cos(angle),.2,Math.sin(angle)),tip=base.clone().addScaledVector(dir,.10),petiole=graph.add({id:`petiole-${n}-${side}`,parentId:'main-stem',attachment:at,path:curve([base,base.clone().lerp(tip,.5),tip]),radius:.009,birth:birth+.02,duration:.09,kind:'petiole',material:stemMat,segments:8,sides:6});shoot.add(petiole.mesh);
   const length=(.97-n*.032)*(.90+rand()*.20),width=.44+rand()*.11,fold=.10+rand()*.13,rippleFrequency=39+rand()*17,tilt=.94+rand()*.27,roll=(rand()-.5)*.18,geo=leafGeometry({length,width,curl:.18+rand()*.32,fold,ripple:.007,rippleFrequency,midrib:.003,nu:25,nv:58});
   const bud=leafGeometry({length,width,curl:1.7,fold:2.6,ripple:.006,nu:25,nv:58});geo.morphAttributes.position=[bud.attributes.position];geo.computeVertexNormals();
   const leaf=new THREE.Mesh(geo,material),pivot=new THREE.Group();pivot.position.copy(tip);pivot.rotation.y=-angle;pivot.add(leaf);shoot.add(pivot);leaf.castShadow=leaf.receiveShadow=true;nodes.push({leaf,pivot,petiole,birth:petiole.birth+.025,duration:.14,angle,n,side,tilt,roll});
  }
  if(n>0&&n<8){for(let b=0;b<6;b++){const a=b*Math.PI/3+n*.3,origin=base.clone().add(new THREE.Vector3(Math.cos(a)*.052,(b%2)*.02,Math.sin(a)*.052));const flower=new THREE.Group();flower.position.copy(origin);flower.rotation.set(.4*Math.sin(a),a,-.5);const petalMat=new THREE.MeshPhysicalMaterial({color:0xfff5d9,roughness:.48,side:THREE.DoubleSide,transmission:.09,thickness:.012});for(let p=0;p<5;p++){const petal=new THREE.Mesh(leafGeometry({length:.12,width:.39,curl:1.0,fold:.06,ripple:0,nu:8,nv:18}),petalMat);petal.rotation.z=p*Math.PI*2/5;flower.add(petal);}shoot.add(flower);flowers.push({flower,birth:.67+n*.012+b*.002});const berry=new THREE.Mesh(new THREE.SphereGeometry(.048,16,12),new THREE.MeshPhysicalMaterial({color:0x7f1912,roughness:.34,clearcoat:.6,clearcoatRoughness:.2}));berry.scale.set(.9,1.12,.9);berry.position.copy(origin).add(new THREE.Vector3(Math.cos(a)*.02,-.015,Math.sin(a)*.02));berry.castShadow=true;shoot.add(berry);berries.push({berry,birth:.82+n*.01+b*.002});}}
 }
 const soilMaterial=new THREE.MeshStandardMaterial({color:0x3d3a2f,roughness:1,side:THREE.DoubleSide});
 const fullSoil=new THREE.Mesh(new THREE.PlaneGeometry(8,8),soilMaterial),cutSoil=new THREE.Mesh(new THREE.PlaneGeometry(8,4),soilMaterial),soilWall=new THREE.Mesh(new THREE.PlaneGeometry(8,1.35),new THREE.MeshStandardMaterial({color:0x39382e,roughness:1,side:THREE.DoubleSide}));
 for(const m of [fullSoil,cutSoil]){m.rotation.x=-Math.PI/2;m.position.y=-.012;m.receiveShadow=true;m.userData.excludeFromFraming=true;root.add(m);}cutSoil.position.z=-2;cutSoil.visible=false;soilWall.position.set(0,-.68,0);soilWall.visible=false;soilWall.userData.excludeFromFraming=true;root.add(soilWall);
 let cut=false;return {root,graph,material,info:{geometry:'seed + attached growing root/stem axes + opposite leaf pairs + petals + fruit',species:'coffee-inspired',growth:'axis extension + independent unfolding, not global scale'},setRootCut(value){cut=value;underground.visible=value;fullSoil.visible=!value;cutSoil.visible=value;soilWall.visible=value;},update(seconds){const age=clamp(seconds/30);graph.update(age);seed.visible=age<.25;seed.scale.set(1,.8+age*1.8,.68);for(const n of nodes){const a=smooth(n.birth,n.birth+n.duration,age);n.pivot.visible=a>.001;n.pivot.position.copy(n.petiole.path.getPointAt(Math.max(0,n.petiole.progress)));n.leaf.scale.set(Math.max(.001,a)**.7,Math.max(.001,a),Math.max(.001,a));n.leaf.morphTargetInfluences[0]=1-a;n.pivot.rotation.z=-.14-a*n.tilt;n.pivot.rotation.x=n.roll+Math.sin(seconds*1.3+n.n)*.017*a;}for(const f of flowers){const a=smooth(f.birth,f.birth+.055,age),abscission=1-smooth(f.birth+.15,f.birth+.25,age);f.flower.visible=a*abscission>.001;f.flower.scale.setScalar(Math.max(.001,a*abscission));}for(const b of berries){const a=smooth(b.birth,b.birth+.10,age);b.berry.visible=a>.001;b.berry.scale.set(.9*a,1.12*a,.9*a);b.berry.material.color.setHSL(.24*(1-a),.72,.18+.04*a);}this.info.growthEvidence=graph.evidence();this.info.rootCut=cut;}};
}
